def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        return '错误：除数不能为零'
    except TypeError:
        return '错误：请输入数字'
    else:
        return f'{a}/{b}={result:.2f}'
    finally:
        print('计算完成')

